151617181920212223242526272829303132333435363738394041from Crypto.Util.number import getPrime, bytes_to_longimport osdef gen_keys(bits=1024): p = getPrime(bits // 2) q = getPrime(bits // 2) n = p * q e = 65537 d = pow(e, -1, (p-1)*(q-1)) return (n, e), dclass Oracle: def __init__(self, n, d): self.n = n self.d = d def decrypt_last_byte(self, c): m = pow(c, self.d, self.n) return m % 256pub, priv = gen_keys(1024)n, e = pubd = privwith open(&quot;flag.txt&quot;, &quot;rb&quot;) as f: flag = f.read()m = bytes_to_long(flag)c = pow(m, e, n)print(f&quot;n = &#123;n&#125;&quot;)print(f&quot;e = &#123;e&#125;&quot;)print(f&quot;c = &#123;c&#125;&quot;)oracle = Oracle(n, d)while True: try: query = int(input(&quot;c&gt; &quot;)) last_byte = oracle.decrypt_last_byte(query) print(f&quot;Last byte: &#123;last_byte&#125;&quot;) except: break 这个题的解法和前面的思路是一样的，只不过这里我们需要构造一个 $k$ 和最后一个字节的映射表来获取 $k$ 的值了。 解题代码示例： 123456789101112131415161718192021222324252627282930313233343536373839404142434445464748495051525354555657585960import mathfrom pwn import *from Crypto.Util.number import long_to_bytesp = process([&#x27;python3&#x27;, &#x27;server.py&#x27;])p.recvuntil(b&quot;n = &quot;)n = int(p.recvline().strip())p.recvuntil(b&quot;e = &quot;)e = int(p.recvline().strip())p.recvuntil(b&quot;c = &quot;)c = int(p.recvline().strip())def query(c_query): p.sendlineafter(b&quot;c&gt; &quot;, str(c_query).encode()) p.recvuntil(b&quot;Last byte: &quot;) return int(p.recvline().strip())# 提前计算映射表，实际上就是求 (-n) 模 256 的逆元# 满足 equation: (k * (-n)) % 256 = b =&gt; k = (b * inv_n) % 256inv_n = pow(-n, -1, 256)x = 0# 总查询次数取决于位数，一次查询泄露一个字节(8位)total_queries = math.ceil(n.bit_length() / 8.0)# 为减少日志输出，我们每10次打印一次进度for i in range(1, total_queries + 1): c_query = (c * pow(pow(256, i, n), e, n)) % n b = query(c_query) # 我们已知 256^i * m % n = 256^i * m - K * n # 当前迭代的余数贡献主要来自于 (-k * n) 模 256 # 通过预先计算好的逆元，可以直接求出减去的个数值 k k = (b * inv_n) % 256 x = x * 256 + k if i % 10 == 0: print(f&quot;[*] 已完成 &#123;i&#125;/&#123;total_queries&#125; 次查询&quot;)print(&quot;[*] 所有查询已完成。&quot;)# 根据所有迭代的 x 值，m 的取值范围最终被限缩到以下闭区间内# [x * n / 256^total_queries, (x+1) * n / 256^total_queries)lower = x * n // (256**total_queries)upper = (x + 1) * n // (256**total_queries)print(f&quot;预期下界: &#123;lower&#125;&quot;)print(f&quot;预期上界: &#123;upper&#125;&quot;)if lower == upper: m = lower print(f&quot;明文 m: &#123;m&#125;&quot;) print(f&quot;Flag : &#123;long_to_bytes(m)&#125;&quot;)else: # 为了容灾计算的精度误差，我们在上下界附近测试真正的明文值 for m in range(lower - 2, upper + 2): if pow(m, e, n) == c: print(f&quot;明文 m: &#123;m&#125;&quot;) print(f&quot;Flag : &#123;long_to_bytes(m)&#125;&quot;) breakp.close() 上一章：RSA加解密专题 - Coppersmith 相关攻击二下一章：回到开始：关于我 相关链接： 参考：CTF Wiki - RSA 选择明密文攻击
